-- All panden in data.building_precomputed with model inputs + RD centroid (read-only).
\set QUIET on
SET work_mem = '64MB';
SET max_parallel_workers_per_gather = 0;
\copy (SELECT bp.building_id, bp.construction_year_bag AS cy, bp.height, bp.address_count, bp.ground_level, bp.surface_area, gr.code AS soil, gw.level AS gw_level, pl.depth AS pleistocene_depth, bs.velocity AS subsidence_velocity, nb.external_id AS buurt, d.external_id AS wijk, m.external_id AS gm_code, m.name AS gm_name, round(ST_X(c.p)::numeric,1) AS x, round(ST_Y(c.p)::numeric,1) AS y, data.indicative_foundation_type(bp.construction_year_bag, bp.height, gr.code, bp.address_count)::text AS tree_type FROM data.building_precomputed bp JOIN geocoder.building b ON b.external_id = bp.building_id LEFT JOIN data.building_geographic_region gr ON gr.building_id = bp.building_id LEFT JOIN data.building_groundwater_level gw ON gw.building_id = bp.building_id LEFT JOIN data.building_pleistocene pl ON pl.building_id = bp.building_id LEFT JOIN data.building_subsidence bs ON bs.building_id = bp.building_id LEFT JOIN geocoder.neighborhood nb ON nb.id = bp.neighborhood_id LEFT JOIN geocoder.district d ON d.id = nb.district_id LEFT JOIN geocoder.municipality m ON m.id = d.municipality_id CROSS JOIN LATERAL (SELECT ST_Transform(ST_PointOnSurface(b.geom), 28992) AS p) c) TO STDOUT WITH CSV HEADER
